insert into public.catalogue_versions (id, version, market, currency, status, quote_basis, price_authority, content_hash, effective_from, activated_at, notes) values
  ('cat_in_2026_10', '2026.10.0', 'IN', 'INR', 'active', 'annual_from_monthly_x12', 'site24x7_public', 'sha256:608c0cf0de2a157745b4c2ccaa84bf99712159b52e206aacb449dcfee075de10', '2026-10-15T00:00:00.000Z', now(), '["Plan prices are published as a monthly rate billed annually. The annual contract value is computed by the pricing engine as monthly x 12 and written into the quote''s calculation trace; it is not stored here.","Add-on prices are published per year and are used verbatim.","Alert Credits are priced per credit, not per pack, and differ by plan (INR 28.50 on WebUptimePack, INR 19 on Enterprise Plus Web).","Basic Additional Check and Advanced Additional Check are genuinely INR 0 on Enterprise. Zero is a real published price here, not a missing value.","The Zoho Store comparison matrix renders ''undefined'' for Mobile Runs and 10GB Log Forwarding rows. Those cells carry no data and are recorded as compatibility-unknown. 10GB Log Forwarding does, however, appear with a real price (INR 950/unit/year) in the add-on price grid for Professional and Enterprise.","Infrastructure and All-in-One list Lite, Professional and Enterprise at identical prices, and the store shows exactly one column for each. They are modelled as one SKU with membership in both families."]'::jsonb);
insert into public.catalogue_sources (id, catalogue_version_id, title, locator, url, surface, retrieved_at, verification_status, caveats) values
  ('src_public_website_monitoring', 'cat_in_2026_10', 'Site24x7 India pricing - Website Monitoring tab', 'Screenshots/Existing Pricing/WebsiteMonitoring.pdf', 'https://www.site24x7.in/pricing.html', 'site24x7_public', '2026-10-15T00:00:00.000Z', 'screenshot_derived', '["Captured as an image-only PDF; figures read visually, no text layer present."]'::jsonb),
  ('src_public_infrastructure', 'cat_in_2026_10', 'Site24x7 India pricing - Infrastructure tab', 'Screenshots/Existing Pricing/Infrastructure.pdf', 'https://www.site24x7.in/pricing.html', 'site24x7_public', '2026-10-15T00:00:00.000Z', 'screenshot_derived', '["Enterprise shown as ''Starts at'' with a Request Price Quote action, so its figure is a floor and not a quotable total."]'::jsonb),
  ('src_public_all_in_one', 'cat_in_2026_10', 'Site24x7 India pricing - All-in-One tab', 'Screenshots/Existing Pricing/AllinOne.pdf', 'https://www.site24x7.in/pricing.html', 'site24x7_public', '2026-10-15T00:00:00.000Z', 'screenshot_derived', '["Lists the same Lite / Professional / Enterprise SKUs and prices as the Infrastructure tab, with different entitlements emphasised."]'::jsonb),
  ('src_public_msp', 'cat_in_2026_10', 'Site24x7 India pricing - MSP tab', 'Screenshots/Existing Pricing/MSP.pdf', 'https://www.site24x7.in/pricing.html', 'site24x7_public', '2026-10-15T00:00:00.000Z', 'screenshot_derived', '["MSP Enterprise shows a price and a Request Price Quote action."]'::jsonb),
  ('src_store_matrix', 'cat_in_2026_10', 'Zoho Store - Site24x7 by OpManager Nexus, plan comparison matrix', 'Screenshots/Pricing/pricingall.pdf (plan header and feature/add-on compatibility rows)', 'https://store.zoho.in/', 'zoho_store', '2026-10-15T00:00:00.000Z', 'screenshot_derived', '["Prices on this surface reflect a signed-in account and include fractional-rupee amounts, so they are treated as account-specific rather than list prices.","Several rows render the literal string ''undefined'' and carry no data."]'::jsonb),
  ('src_store_addon_prices', 'cat_in_2026_10', 'Zoho Store - Site24x7 add-on price grid, six plan columns', 'Screenshots/Pricing/pricingall.pdf (add-on price cards, read column by column)', 'https://store.zoho.in/', 'zoho_store', '2026-10-15T00:00:00.000Z', 'screenshot_derived', '["The only source for add-on prices; the public pricing page does not itemise them.","Each column was cropped and read in isolation so a price cannot be attributed to the wrong plan."]'::jsonb);
