insert into public.catalogue_plans (id, catalogue_version_id, name, store_name, summary, price_monthly_annual_billed, price_month_to_month, quote_on_request, price_is_floor, polling_frequency, monitoring_locations, support_tier, store_price_monthly_annual_billed, source_id, display_order) values
  ('plan_web_uptime', 'cat_in_2026_10', 'Web Uptime', 'WEBUPTIMEPACK', 'Website and internet-service uptime checks from a wide location set.', 85500, 95000, false, false, '1 minute', 32, 'Email support', 85500, 'src_public_website_monitoring', 1),
  ('plan_web_perf', 'cat_in_2026_10', 'Web Perf', 'WEBPERF', 'Website performance monitoring with transaction monitors and real user monitoring.', 342000, 370500, false, false, '1 minute', 8, 'Classic support', 333450, 'src_public_website_monitoring', 2),
  ('plan_enterprise_plus_web', 'cat_in_2026_10', 'Enterprise Plus Web', 'ENTERPRISE PLUS WEB', 'Large-scale website and transaction monitoring at the fastest polling frequency.', 8540500, 9490500, false, false, '30 seconds', 16, 'Classic support', 8540500, 'src_public_website_monitoring', 3),
  ('plan_lite', 'cat_in_2026_10', 'Lite', 'LITE', 'Entry plan covering servers, websites, network, applications and logs with small included quantities.', 85500, 95000, false, false, '1 minute', 8, 'Email support', 85500, 'src_public_infrastructure', 1),
  ('plan_professional', 'cat_in_2026_10', 'Professional', 'PROFESSIONAL', 'Mid-tier plan covering servers, applications, websites, network components and log ingestion.', 399000, 465500, false, false, '1 minute', 8, 'Classic support', 395042, 'src_public_infrastructure', 2),
  ('plan_enterprise', 'cat_in_2026_10', 'Enterprise', 'ENTERPRISE', 'Large-scale plan with every Professional feature plus anomaly detection, event correlation and infrastructure events.', 5937500, 7125000, true, true, '10 seconds', 16, 'Classic support', 5936708, 'src_public_infrastructure', 3),
  ('plan_msp', 'cat_in_2026_10', 'MSP', null, 'For managed service providers monitoring multiple customer estates from one account.', 513000, 560500, false, false, '1 minute', 8, 'Classic support', null, 'src_public_msp', 1),
  ('plan_msp_enterprise', 'cat_in_2026_10', 'MSP Enterprise', null, 'Every MSP feature plus anomaly detection, event correlation, infrastructure events and NCM.', 2137500, 2365500, true, false, '1 minute', 8, 'Classic support', null, 'src_public_msp', 2);
